    int count = 1; // Устанавливаем номер элемента списка по умолчанию
    while (true) { // Запускаем бесконечный цикл для добавления элементов в список
        cout << "[" << count << "]: "; // Номер элемента
        getline(cin, input);
        if (input == "") { // Если элемент не введен (пустая строка), прерываем цикл
            break;
        } else { // Иначе, добавляем элемент в список и увеличиваем номер элемента
            lista.push_back(input);
            count++;
        }
    }

    if (lista.empty()) { // если список пустой, выводим сообщение об ошибке и завершаем программу
        cerr << "Ошибка: список пуст!" << endl;
        return 1;
    }

    sort(lista.begin(), lista.end()); // Сортируем список перед поиском

    while (true) { // бесконечный цикл
        cout << "Введите элемент, который нужно найти (для выхода введите /q):" << endl;
        getline(cin, item); // Получаем ввод пользователя
        if (item == "/q") {
            break;
        }
        if (item.empty()) { // Если строка пустая, то цикл заново
            cerr << "Ошибка: введена пустая строка!" << endl;
            continue;
        }
        index = binarySearch(lista, item); // Ищем элемент в списке
        if (index == -1) { // Если элемент не найден, выводим сообщение об ошибке
            cerr << "Элемент не найден!" << endl;
        } else {
            cout << "Элемент найден в списке! Индекс: " << index + 1 << endl;
        }
    }
    return 0;
}

