// Максимальное количество вершин в графе
#define MAX_VERTICES 100

// Функция для нахождения максимума двух чисел
int max(int a, int b) {
    return (a > b) ? a : b;
}

// Функция для нахождения наиболее надежного пути между двумя вершинами
double findMostReliablePath(int graph[MAX_VERTICES][MAX_VERTICES], int vertices, int source, int destination) {
    // Инициализация массива для хранения надежностей путей
    double reliability[MAX_VERTICES];
    for (int i = 0; i < vertices; i++) {
        reliability[i] = 0.0;
    }

    // Начальная надежность источника равна 1.0
    reliability[source] = 1.0;

    // Поиск наиболее надежного пути с использованием динамического программирования
    for (int i = 0; i < vertices - 1; i++) {
        for (int u = 0; u < vertices; u++) {
            for (int v = 0; v < vertices; v++) {
                if (graph[u][v] != 0) {
                    // Обновление надежности пути, если найден более надежный путь
                    reliability[v] = max(reliability[v], reliability[u] * graph[u][v]);
                }
            }
        }
    }

    // Возвращаем наиболее надежный путь между источником и пунктом назначения
    return reliability[destination];
}

int main() {
    int vertices; // Количество вершин в графе
    int graph[MAX_VERTICES][MAX_VERTICES]; // Матрица смежности графа

    // Ввод количества вершин в графе
    std::cout << "Введите количество вершин в графе: ";
    std::cin >> vertices;

    // Ввод матрицы смежности графа
    std::cout << "Введите матрицу смежности графа:\n";
    for (int i = 0; i < vertices; i++) {
        for (int j = 0; j < vertices; j++) {
            std::cin >> graph[i][j];
        }
    }

    int source, destination; // Источник и пункт назначения
    std::cout << "Введите источник и пункт назначения: ";
    std::cin >> source >> destination;

    // Поиск наиболее надежного пути
    double reliability = findMostReliablePath(graph, vertices, source, destination);

    // Вывод результата
    std::cout << "Наиболее надежный путь между " << source << " и " << destination << " имеет надежность: " << reliability << std::endl;

    return 0;
}
